static lstr L873 = {-1, 2248, "// std/bytes. A bytes value is an lstr whose data need not be UTF-8, so a\012// string converts to bytes by sharing its buffer.\012\012static lstr* narra_bytes_from_string(lstr* s) {\012  lstr_retain(s);\012  return s;\012}\012\012// The offset of the first byte where p[0..n) stops being valid UTF-8, or -1.\012// Overlong forms, surrogates and values above U+10FFFF are invalid.\012static int64_t narra_bytes_utf8_error(const unsigned char* p, int64_t n) {\012  int64_t i = 0;\012  while (i < n) {\012    unsigned char c = p[i];\012    int64_t k;\012    uint32_t cp;\012    if (c < 0x80) { i++; continue; }\012    if (c >= 0xC2 && c <= 0xDF) { k = 1; cp = c & 0x1F; }\012    else if (c >= 0xE0 && c <= 0xEF) { k = 2; cp = c & 0x0F; }\012    else if (c >= 0xF0 && c <= 0xF4) { k = 3; cp = c & 0x07; }\012    else return i;\012    if (i + k >= n) return i;\012    for (int64_t j = 1; j <= k; j++) {\012      if ((p[i + j] & 0xC0) != 0x80) return i;\012      cp = (cp << 6) | (p[i + j] & 0x3F);\012    }\012    if (k == 2 && (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF))) return i;\012    if (k == 3 && (cp < 0x10000 || cp > 0x10FFFF)) return i;\012    i += k + 1;\012  }\012  return -1;\012}\012\012// Valid UTF-8 shares the buffer as a string; otherwise *err names the offset.\012static bool narra_bytes_to_string(lstr* b, lstr** out, lstr** err) {\012  int64_t bad = narra_bytes_utf8_error((const unsigned char*)b->data, b->len);\012  if (bad >= 0) {\012    char buf[64];\012    snprintf(buf, sizeof buf, \"invalid UTF-8 at byte %\" PRId64, bad);\012    *err = lstr_from_cstr(buf);\012    return false;\012  }\012  lstr_retain(b);\012  *out = b;\012  return true;\012}\012\012static int64_t narra_bytes_length(lstr* b) { return b->len; }\012\012static bool narra_bytes_at(lstr* b, int64_t index, uint8_t* out) {\012  if (index < 0 || index >= b->len) return false;\012  *out = (uint8_t)b->data[index];\012  return true;\012}\012\012// Copies bytes start up to but not including end.\012static bool narra_bytes_slice(lstr* b, int64_t start, int64_t end, lstr** out) {\012  if (start < 0 || end < start || end > b->len) return false;\012  lstr* s = lstr_new(end - start);\012  memcpy(s->data, b->data + start, (size_t)(end - start));\012  *out = s;\012  return true;\012}\012\012static lstr* narra_bytes_from_raw(const uint8_t* data, int64_t len) {\012  lstr* s = lstr_new(len);\012  if (len > 0) memcpy(s->data, data, (size_t)len);\012  return s;\012}\012"};
static lstr L874 = {-1, 18, "std/internal/clock"};
static lstr L875 = {-1, 857, "// std/internal/clock. The monotonic clock, the wall clock and sleep.\012#include <errno.h>\012#include <time.h>\012\012static int64_t narra_clock_monotonic_nanos(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_MONOTONIC, &now);\012  return (int64_t)now.tv_sec * 1000000000 + (int64_t)now.tv_nsec;\012}\012\012static int64_t narra_clock_wall_millis(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_REALTIME, &now);\012  return (int64_t)now.tv_sec * 1000 + (int64_t)now.tv_nsec / 1000000;\012}\012\012// Sleeps for the given nanoseconds, again after a signal; a value of zero or less returns at once.\012static void narra_clock_sleep_nanos(int64_t nanos) {\012  if (nanos <= 0) return;\012  struct timespec remaining;\012  remaining.tv_sec = (time_t)(nanos / 1000000000);\012  remaining.tv_nsec = (long)(nanos % 1000000000);\012  while (nanosleep(&remaining, &remaining) != 0 && errno == EINTR) {\012  }\012}\012"};
static lstr L876 = {-1, 20, "std/internal/entropy"};
static lstr L877 = {-1, 448, "// std/internal/entropy. A seed from the operating system's random source.\012#include <time.h>\012\012static int64_t narra_entropy_seed(void) {\012  uint64_t seed = 0;\012  FILE* source = fopen(\"/dev/urandom\", \"rb\");\012  if (source != NULL) {\012    if (fread(&seed, sizeof seed, 1, source) != 1) seed = 0;\012    fclose(source);\012  }\012  if (seed == 0) {\012    seed = (uint64_t)time(NULL) * 6364136223846793005ULL + (uint64_t)(uintptr_t)&seed;\012  }\012  return (int64_t)seed;\012}\012"};
static lstr L878 = {-1, 17, "std/internal/host"};
static lstr L879 = {-1, 595, "// std/internal/host. The operating system and the machine the C compiler builds for.\012\012// 0 when the system is not one of the supported targets, else 1 for macOS and 2 for Linux.\012static int64_t narra_host_os(void) {\012#if defined(__APPLE__)\012  return 1;\012#elif defined(__linux__)\012  return 2;\012#else\012  return 0;\012#endif\012}\012\012// 0 when the machine is not one of the supported targets, else 1 for Arm64 and 2 for X86_64.\012static int64_t narra_host_arch(void) {\012#if defined(__aarch64__) || defined(__arm64__)\012  return 1;\012#elif defined(__x86_64__) || defined(__amd64__)\012  return 2;\012#else\012  return 0;\012#endif\012}\012"};
